/**
 * CoinBonus compatibility helper for Focus Quest Civilization Engine.
 * Milestone 5B.2: Building Catalog & Storage Schema v2 Migration
 *
 * Prepares the integration bridge with Phase 5A CoinBonus architecture:
 * Extracts pure, additive CoinBonus descriptors from placed building instances
 * without modifying RewardEngine or SessionCoordinator.
 */

import { CoinBonus } from '../../types/economy.ts';
import { BuildingInstance } from './buildingTypes.ts';
import { getBuildingDefinition } from './buildingCatalog.ts';

/**
 * Extracts all additive CoinBonus entries generated by active building instances.
 * - Decorative and Focus Support buildings produce no bonuses.
 * - Buildings with a COIN_BONUS effect provide:
 *     rate = effect.rate * building.level
 * - Returns an immutable array of CoinBonus ready for aggregateCoinBonus().
 */
export function extractBuildingCoinBonuses(
  buildings: readonly BuildingInstance[] | null | undefined
): readonly CoinBonus[] {
  if (!buildings || buildings.length === 0) {
    return [];
  }

  const bonuses: CoinBonus[] = [];

  for (const instance of buildings) {
    if (!instance || typeof instance.id !== 'string' || !instance.id) {
      continue;
    }

    const definition = getBuildingDefinition(instance.definitionId);
    if (!definition || !definition.effects) {
      continue;
    }

    const level =
      typeof instance.level === 'number' && Number.isInteger(instance.level) && instance.level >= 1
        ? instance.level
        : 1;

    for (const effect of definition.effects) {
      if (effect.type === 'COIN_BONUS') {
        const baseRate = effect.rate;
        if (typeof baseRate === 'number' && Number.isFinite(baseRate) && baseRate > 0) {
          bonuses.push({
            id: `building:${instance.id}`,
            source: 'BUILDING',
            rate: baseRate * level,
          });
        }
      }
    }
  }

  return bonuses;
}
